import { createHash } from "node:crypto";
import pinned from "@/data/erc8060Erc8098ScientificDossier.json";

/**
 * Generated by the pinned ERC-8060 / ERC-8098 local-EVM workflow.
 * This is a fixed, read-only scientific snapshot. Never create a candidate or
 * calculate a compatibility verdict in a web route or presentation component.
 */
export type ScientificDossier = typeof pinned;
export const DOSSIER_SNAPSHOT_SHA256 =
  "9cfb5bbd4bf0b98a424827a13057507d5ef3f3ea3e30e256eb9cc8cdf2ef13a6";
export const DOSSIER_EVIDENCE_RUN =
  "https://github.com/ten-io-meta/open-erc-composition-laboratory/actions/runs/44963511127";
export const DOSSIER_PROTOCOL_PAIR = ["ERC-8060", "ERC-8098"] as const;

export function normalizeErc(value: string | null): string | null {
  const match = value?.trim().toUpperCase().match(/^(?:ERC-?)?([1-9][0-9]*)$/);
  return match ? "ERC-" + match[1] : null;
}

export function isDossierPair(a: string, b: string): boolean {
  return (a === DOSSIER_PROTOCOL_PAIR[0] && b === DOSSIER_PROTOCOL_PAIR[1]) ||
    (b === DOSSIER_PROTOCOL_PAIR[0] && a === DOSSIER_PROTOCOL_PAIR[1]);
}

/** Fail closed if data are altered without a new scientific CI-attested snapshot. */
export function getVerifiedScientificDossier(): ScientificDossier {
  const sha = createHash("sha256")
    .update(JSON.stringify(pinned))
    .digest("hex");
  if (sha !== DOSSIER_SNAPSHOT_SHA256) {
    throw new Error("OECL_DOSSIER_CONTENT_HASH_MISMATCH");
  }
  if (
    pinned.schemaVersion !== "OECL_USER_SCIENTIFIC_DOSSIER_V1" ||
    pinned.scope !== "PINNED_LOCAL_HARDHAT_EVM" ||
    pinned.verdict !== "INCONCLUSIVE" ||
    pinned.candidateAdmission !== "NOT_ADMITTED" ||
    pinned.universalCompatibilityEstablished !== false ||
    pinned.discovery.origin !== "COMPILER_RESOLVED_SOLIDITY_AST_ONLY" ||
    pinned.discovery.status !== "UNEVALUATED_SOURCE_HYPOTHESIS" ||
    pinned.experiment.chainId !== 31337 ||
    pinned.experiment.propertyStatus !== "OBSERVED_IN_PINNED_LOCAL_EVM" ||
    pinned.experiment.localConstraintResult !== "SUPPORT" ||
    pinned.scientificQuestions.total !== 10 ||
    pinned.scientificQuestions.scopedObserved !== 10 ||
    pinned.scientificQuestions.sourceCoverageComplete !== false ||
    pinned.scientificQuestions.allQuestionsResolved !== false ||
    pinned.adversarial.status !== "PARTIAL_COVERAGE" ||
    pinned.participants.length !== 2 ||
    pinned.adversarial.untested.length !== 9 ||
    pinned.artifacts.graph.sha256.length !== 64 ||
    pinned.artifacts.evm.sha256.length !== 64
  ) {
    throw new Error("OECL_DOSSIER_SCIENTIFIC_INVARIANT_MISMATCH");
  }
  return pinned;
}
